insert into chunks (document_id, chunk_index, heading, content) values
('3ec40391-e0da-4687-bd26-9ad3a721bff7', 40, null, 'c) musí zrušit své předchozí určení finančního závazku jako nástroje oceňovaného reálnou hodnotou do hospodářského výsledku, pokud toto určení bylo dříve provedeno v souladu s podmínkou stanovenou v odst. 4.2.2 písm. a), avšak v důsledku použití tohoto standardu tato podmínka již není naplněna; d) může určit finanční závazek jako nástroj oceňovaný reálnou hodnotou do hospodářského výsledku, pokud by toto určení dříve nenaplňovalo podmínku stanovenou v odst. 4.2.2 písm. a), avšak v důsledku použití tohoto standardu je nyní tato podmínka naplněna. Takové určení a zrušení musí být provedeno na základě skutečností a okolností existujících k datu prvotní aplikace tohoto standardu. Tato klasifikace musí být provedena zpětně. Přechodná ustanovení pro prvek předčasného splacení s negativní kompenzací 7.2.29 7.2.30 7.2.31 7.2.32 a) musí zrušit své předchozí určení finančního aktiva jako aktiva oceňovaného reálnou hodnotou vykázanou do hospodářského výsledku, pokud toto určení bylo učiněno v souladu s podmínkou stanovenou v odstavci 4.1.5, avšak v důsledku použití těchto změn daná podmínka již není splněna; b) může určit finanční aktivum za oceňované reálnou hodnotou vykázanou do hospodářského výsledku, pokud by toto určení dříve nenaplňovalo podmínku stanovenou v odstavci 4.1.5, avšak v důsledku použití těchto změn je nyní tato podmínka splněna;'),
('3ec40391-e0da-4687-bd26-9ad3a721bff7', 41, null, 'c) musí zrušit své předchozí určení finančního závazku jako závazku oceňovaného reálnou hodnotou vykázanou do hospodářského výsledku, pokud toto určení bylo učiněno v souladu s podmínkou stanovenou v odst. 4.2.2 písm. a), avšak v důsledku použití těchto změn daná podmínka již není splněna, a d) může určit finanční závazek za oceňovaný reálnou hodnotou vykázanou do hospodářského výsledku, pokud by toto určení dříve nenaplňovalo podmínku stanovenou v odst. 4.2.2 písm. a), avšak v důsledku použití těchto změn je nyní tato podmínka splněna. Uvedené určení a zrušení musí být provedeno na základě skutečností a okolností existujících k datu prvotního použití těchto změn. Tato klasifikace musí být provedena zpětně. 7.2.33 7.2.34 a) předchozí kategorii oceňování a účetní hodnotu stanovenou bezprostředně před použitím těchto změn; b) novou kategorii oceňování a účetní hodnotu stanovenou po použití těchto změn; c) účetní hodnotu jakýchkoli finančních aktiv a finančních závazků ve výkazu o finanční pozici, které byly dříve určeny za oceňované reálnou hodnotou vykázanou do hospodářského výsledku, avšak již takto určeny nejsou, a d) důvody pro určení nebo zrušení určení finančních aktiv nebo finančních závazků jako aktiv nebo závazků oceněných reálnou hodnotou vykázanou do hospodářského výsledku. Přechodné období pro roční zdokonalení standardů IFRS 7.2.35 Přechod na IFRS 17 ve znění z června 2020'),
('3ec40391-e0da-4687-bd26-9ad3a721bff7', 42, null, '7.2.36 7.2.37 7.2.38 7.2.39 a) musí zrušit své předchozí určení finančního závazku jako závazku oceňovaného reálnou hodnotou vykázanou do hospodářského výsledku, pokud toto určení bylo učiněno v souladu s podmínkou stanovenou v odst. 4.2.2 písm. a), avšak v důsledku použití těchto změn daná podmínka již není splněna, a b) může určit finanční závazek za oceňovaný reálnou hodnotou vykázanou do hospodářského výsledku, pokud by toto určení dříve nenaplňovalo podmínku stanovenou v odst. 4.2.2 písm. a), avšak v důsledku použití těchto změn je nyní tato podmínka splněna. Uvedené určení a zrušení musí být provedeno na základě skutečností a okolností existujících k datu prvotního použití těchto změn. Tato klasifikace musí být provedena zpětně. 7.2.40 7.2.41 7.2.42 a) předchozí klasifikaci, včetně případné předchozí kategorie oceňování, a účetní hodnotu stanovenou bezprostředně před použitím těchto změn; b) novou kategorii oceňování a účetní hodnotu stanovenou po použití těchto změn; c) účetní hodnotu všech finančních závazků ve výkazu o finanční pozici, které byly dříve určeny za oceněné reálnou hodnotou do hospodářského výsledku, avšak již takto určeny nejsou, a d) důvody pro případné určení nebo zrušení určení finančních závazků jako závazků oceněných reálnou hodnotou do hospodářského výsledku. Přechodná ustanovení pro Reformu referenčních úrokových sazeb – fáze 2'),
('3ec40391-e0da-4687-bd26-9ad3a721bff7', 43, null, '7.2.43 7.2.44 a) účetní jednotka ukončila zajišťovací vztah výhradně kvůli změnám požadovaným reformou referenčních úrokových sazeb a nemusela by bývala tento zajišťovací vztah ukončit, pokud by byly uvedené změny v té době použity, a b) na počátku účetního období, kdy účetní jednotka poprvé použila tyto změny (datum prvotního použití těchto změn), splňoval tento ukončený zajišťovací vztah kritéria způsobilosti pro zajišťovací účetnictví (poté, co účetní jednotka vzala tyto změny v úvahu). 7.2.45 7.2.46 7.3   ZRUŠENÍ IFRIC 9, IFRS 9 (2009), IFRS 9 (2010) A IFRS 9 (2013) 7.3.1 7.3.2 Dodatek A Definice pojmů Tento dodatek je nedílnou součástí standardu. dvanáctiměsíční očekávané úvěrové ztráty Část očekávaných úvěrových ztrát za dobu trvání představující očekávané úvěrové ztráty, jež vznikají v důsledku selhání finančního nástroje, které může nastat během dvanácti měsíců od data vykázání. naběhlá hodnota finančního aktiva nebo finančního závazku Částka, jíž jsou finanční aktiva nebo finanční závazky oceněny při prvotním uznání, snížená o splátky jistiny a zvýšená nebo snížená – s použitím metody efektivní úrokové míry – o kumulativní amortizaci prémie či diskontu, tj. rozdílu mezi počáteční hodnotou a hodnotou při splatnosti, a u finančních aktiv upravená o případnou opravnou položku. smluvní aktiva Ta práva, která jsou vymezena ve standardu IFRS 15 Výnosy ze smluv se zákazníky a která jsou účtována v souladu s tímto standardem pro účely uznání a ocenění zisků nebo ztrát ze znehodnocení. úvěrově znehodnocené finanční aktivum'),
('3ec40391-e0da-4687-bd26-9ad3a721bff7', 44, null, 'Finanční aktivum je úvěrově znehodnoceno, pokud nastala jedna či více událostí, které mají nepříznivý dopad na odhadované budoucí peněžní toky spojené s daným finančním aktivem. Mezi důkazy o tom, že došlo k úvěrovému znehodnocení finančního aktiva, patří pozorovatelné informace o těchto událostech: a) podstatné finanční problémy emitenta nebo dlužníka; b) porušení smlouvy, např. neplnění závazku nebo nedodržení splatnosti; c) věřitel či věřitelé udělili dlužníkovi z ekonomických či smluvních důvodů souvisejících s finančními obtížemi dlužníka úlevu (úlevy), které by jinak neudělili; d) stává se pravděpodobným zahájení konkurzu či jiná finanční reorganizace dlužníka; e) zánik aktivního trhu pro toto finanční aktivum z důvodu finančních potíží nebo f) nákup nebo vznik finančního aktiva s výraznou slevou, která odráží vzniklé úvěrové ztráty. Někdy může dojít k tomu, že nebude možné určit jednotlivou izolovanou/nespojitou událost – úvěrové znehodnocení finančních aktiv mohlo být způsobeno kombinovaným účinkem více událostí. úvěrová ztráta'),
('3ec40391-e0da-4687-bd26-9ad3a721bff7', 45, null, 'Rozdíl mezi všemi smluvními peněžními toky splatnými účetní jednotce podle smlouvy a všemi peněžními toky, jejichž inkaso účetní jednotka očekává (tj. všechny hotovostní schodky), diskontovaný původní efektivní úrokovou mírou (nebo efektivní úrokovou mírou upravenou o úvěrové riziko pro nakoupená nebo vzniklá úvěrově znehodnocená finanční aktiva). Účetní jednotka odhadne peněžní toky na základě posouzení všech smluvních podmínek finančního nástroje (například opce na předčasné splacení, prodloužení nebo kupní a podobné opce) po očekávanou dobu trvání finančního nástroje. Uvažované peněžní toky zahrnují peněžní toky z prodeje drženého kolaterálu či jiných úvěrových posílení, jež jsou nedílnou součástí smluvních podmínek. Předpokládá se, že očekávanou dobu trvání finančního nástroje lze spolehlivě odhadnout. Avšak ve výjimečných případech, kdy není možné očekávanou dobu trvání finančního nástroje spolehlivě odhadnout, použije účetní jednotka zbývající smluvní dobu trvání finančního nástroje. efektivní úroková míra upravená o úvěrové riziko'),
('3ec40391-e0da-4687-bd26-9ad3a721bff7', 46, null, 'Úroková míra, která přesně diskontuje odhadované budoucí peněžní platby nebo příjmy po očekávanou dobu trvání finančního aktiva na naběhlou hodnotu finančního aktiva, kterým je nakoupené nebo vzniklé úvěrově znehodnocené finanční aktivum. Při výpočtu efektivní úrokové míry upravené o úvěrové riziko účetní jednotka odhadne očekávané peněžní toky na základě uvážení všech smluvních podmínek finančního aktiva (například opce na předčasné splacení, prodloužení nebo kupní a podobné opce) a očekávaných úvěrových ztrát. Výpočet zahrnuje všechny poplatky a úroky, které jsou placeny nebo přijaty mezi smluvními stranami a které jsou nedílnou součástí efektivní úrokové míry (viz odstavce B5.4.1–B5.4.3), transakční náklady a všechny ostatní prémie a diskonty. Předpokládá se, že peněžní toky a očekávanou délku trvání skupiny podobných finančních nástrojů lze spolehlivě odhadnout. Avšak v těch výjimečných případech, kdy není možné peněžní toky nebo zbývající dobu trvání finančního nástroje (nebo skupiny finančních nástrojů) spolehlivě odhadnout, musí účetní jednotka použít smluvní peněžní toky za celou dobu smluvního trvání finančního nástroje (nebo skupiny finančních nástrojů). vynětí, vyjmutí Odúčtování dříve uznaného finančního aktiva nebo finančního závazku z výkazu o finanční pozici účetní jednotky. derivát Finanční nástroj nebo jiná smlouva spadající do působnosti tohoto standardu a vyznačující se všemi třemi níže uvedenými znaky:'),
('3ec40391-e0da-4687-bd26-9ad3a721bff7', 47, null, 'a) jeho hodnota se mění v závislosti na změně dané úrokové míry, ceny finančního nástroje, ceny komodity, měnového kurzu, cenového nebo úrokového indexu, úvěrového ratingu či úvěrového indexu nebo jiné proměnné (někdy nazývané „podkladová proměnná“). Pokud tato proměnná nemá finanční charakter, nesmí být specifická pro některou ze smluvních stran; b) nevyžaduje žádnou čistou počáteční investici nebo vyžaduje čistou počáteční investici nižší, než jaká by byla požadována u ostatních typů smluv, u kterých by bylo možné očekávat podobnou reakci na změny tržních podmínek; c) bude vypořádán v budoucnosti. dividendy Rozdělení zisků držitelům kapitálových nástrojů poměrně k jimi drženému podílu na konkrétní třídě kapitálu. metoda efektivní úrokové míry Metoda, která je použita při výpočtu naběhlé hodnoty finančního aktiva nebo finančního závazku a při alokaci a uznání úrokového výnosu nebo úrokového nákladu do hospodářského výsledku za dané období. efektivní úroková míra'),
('3ec40391-e0da-4687-bd26-9ad3a721bff7', 48, null, 'Úroková míra, která přesně diskontuje odhadované budoucí peněžní platby nebo příjmy po očekávanou dobu trvání finančního aktiva nebo finančního závazku na hrubou účetní hodnotu finančního aktiva nebo na naběhlou hodnotu finančního závazku. Při výpočtu efektivní úrokové míry musí účetní jednotka odhadnout očekávané peněžní toky s uvážením všech smluvních podmínek finančního nástroje (například opce na předčasné splacení, prodloužení nebo kupní a podobné opce), ale nesmí brát v úvahu očekávané úvěrové ztráty. Výpočet zahrnuje všechny poplatky a úroky, které jsou placeny nebo přijaty mezi smluvními stranami a které jsou nedílnou součástí efektivní úrokové míry (viz odstavce B5.4.1–B5.4.3), transakční náklady a všechny ostatní prémie a diskonty. Předpokládá se, že peněžní toky a očekávanou délku trvání skupiny podobných finančních nástrojů lze spolehlivě odhadnout. Avšak v těch výjimečných případech, kdy není možné peněžní toky nebo očekávanou dobu trvání finančního nástroje (nebo skupiny finančních nástrojů) spolehlivě odhadnout, musí účetní jednotka použít smluvní peněžní toky za celou dobu smluvního trvání finančního nástroje (nebo skupiny finančních nástrojů). očekávané úvěrové ztráty Vážený průměr úvěrových ztrát, kde vahami jsou příslušná rizika neplnění závazků. smlouva o finanční záruce Smlouva, která vyžaduje, aby výstavce provedl určitou platbu za účelem odškodnění držitele za ztrátu, kterou utrpí, protože určitý dlužník neprovede platbu v řádné nebo upravené lhůtě splatnosti stanovené v podmínkách dluhového nástroje.'),
('3ec40391-e0da-4687-bd26-9ad3a721bff7', 49, null, 'finanční závazek oceněný reálnou hodnotou do hospodářského výsledku Finanční závazek, který splňuje jednu z níže uvedených podmínek: a) splňuje definici finančního závazku určeného k obchodování; b) účetní jednotka jej při prvotním uznání označí jako nástroj v reálné hodnotě vykázané do hospodářského výsledku v souladu s odstavcem 4.2.2 nebo 4.3.5; c) při prvotním uznání nebo následně je označen jako nástroj v reálné hodnotě vykázané do hospodářského výsledku v souladu s odstavcem 6.7.1. závazný příslib Závazná dohoda o směně konkrétního objemu prostředků za konkrétní cenu ke konkrétnímu datu (datům) v budoucnosti. očekávaná transakce Nezávazná, ale očekávaná budoucí transakce. hrubá účetní hodnota finančního aktiva Naběhlá hodnota finančního aktiva před úpravou o případnou opravnou položku. zajišťovací poměr Vztah mezi množstvím zajišťovacího nástroje a množstvím zajištěné položky z hlediska jejich poměrných vah. určený k obchodování Finanční aktivum nebo finanční závazek, které: a) byly pořízeny nebo vznikly v zásadě za účelem prodeje nebo zpětné koupě v blízké budoucnosti; b) při prvotním uznání jsou součástí portfolia finančních nástrojů, které jsou společně řízeny a u kterých je v poslední době doloženo obchodování realizované pro krátkodobý zisk; c) jsou derivátem (kromě derivátu, který je smlouvou o finanční záruce nebo plní funkci efektivního zajišťovacího nástroje). zisk nebo ztráta ze znehodnocení'),
('3ec40391-e0da-4687-bd26-9ad3a721bff7', 50, null, 'Zisky nebo ztráty, které jsou uznány do hospodářského výsledku podle odstavce 5.5.8 a které vznikají použitím požadavků týkajících se znehodnocení hodnoty uvedených v oddíle 5.5. očekávané úvěrové ztráty za dobu trvání Očekávané úvěrové ztráty, jež vznikají v důsledku všech možných nedodržení závazků během očekávané doby trvání finančního nástroje. opravná položka Opravná položka na očekávané úvěrové ztráty z finančních aktiv oceněných podle odstavce 4.1.2, pohledávek vyplývajících z leasingu a smluvních aktiv, kumulovaných znehodnocení finančních aktiv oceněných podle odstavce 4.1.2A a rezervy na očekávané úvěrové ztráty z úvěrových příslibů a smluv o finančních zárukách. zisk nebo ztráta z modifikace'),
('3ec40391-e0da-4687-bd26-9ad3a721bff7', 51, null, 'Částka vyplývající z úpravy hrubé účetní hodnoty finančního aktiva, která má odrážet nově sjednané nebo modifikované smluvní peněžní toky. Účetní jednotka vypočítá novou hrubou účetní hodnotu finančního aktiva jako současnou hodnotu odhadovaných budoucích peněžních výdajů nebo příjmů po očekávanou dobu trvání nově sjednaného nebo modifikovaného finančního aktiva diskontovaných původní efektivní úrokovou mírou finančního aktiva (nebo původní efektivní úrokovou mírou upravenou o úvěrové riziko pro nakoupená nebo vzniklá úvěrově znehodnocená finanční aktiva) nebo případně revidovanou efektivní úrokovou mírou vypočtenou podle odstavce 6.5.10. Při odhadování očekávaných peněžních toků z finančního aktiva musí účetní jednotka uvážit všechny smluvní podmínky finančního aktiva (například opce na předčasné splacení, prodloužení nebo kupní a podobné opce), ale nesmí brát v úvahu očekávané úvěrové ztráty, ledaže jde o nakoupené nebo vzniklé úvěrově znehodnocené finanční aktivum, v takovém případě účetní jednotka uvažuje i očekávané provozní úvěrové ztráty, které byly zváženy při výpočtu původní efektivní úrokové míry upravené o úvěrové riziko. po splatnosti Finanční aktivum je po splatnosti, jestliže protistrana neprovedla platbu k datu, kdy byla daná platba na základě smlouvy splatná. nakoupené nebo vzniklé úvěrově znehodnocené finanční aktivum Nakoupené nebo vzniklé finanční aktivum nebo aktiva, úvěrově znehodnocená při prvotním uznání. den reklasifikace První den prvního účetního období po změně obchodního modelu, v jejímž důsledku účetní jednotka reklasifikovala finanční aktiva.'),
('3ec40391-e0da-4687-bd26-9ad3a721bff7', 52, null, 'spotový nákup nebo prodej Koupě nebo prodej finančního aktiva podle smlouvy, jejíž podmínky vyžadují dodání aktiva ve lhůtě stanovené obecně právní úpravou nebo konvencemi daného trhu. transakční náklady Přírůstkové náklady, které přímo souvisejí s nabytím, vydáním nebo vyřazením finančního aktiva nebo závazku (viz odstavec B5.4.8). Přírůstkový náklad je takový náklad, který by nevznikl, pokud by účetní jednotka nenabyla či nepozbyla finančního nástroje nebo by jej nevydala. Následující pojmy jsou definovány v bodě 11 IAS 32, v dodatku A IFRS 7, dodatku A IFRS 13 nebo dodatku A IFRS 15 a v tomto standardu se používají ve významech definovaných v IAS 32, IFRS 7, IFRS 13 nebo IFRS 15: a) úvěrové riziko (52); b) kapitálový nástroj; c) reálná hodnota; d) finanční aktivum; e) finanční nástroj; f) finanční závazek; g) transakční cena. Dodatek B Aplikační příručka Tento dodatek je nedílnou součástí standardu.'),
('3ec40391-e0da-4687-bd26-9ad3a721bff7', 53, 'B2.5', 'a) I když smlouva o finanční záruce splňuje definici pojistné smlouvy podle IFRS 17 (viz odst. 7 písm. e) IFRS 17), je-li přenesené riziko podstatné, bude o ní ručitel účtovat v souladu s tímto standardem. Každopádně, pokud výstavce předem explicitně stanovil, že takové smlouvy považuje za smlouvy pojistné a použil při jejich účtování postupy platné pro pojistné smlouvy, může sám rozhodnout, použije-li pro evidenci takových smluv o finančních zárukách tento standard nebo IFRS 17. Podle odstavce 5.1.1 tohoto standardu se smlouva o finanční záruce prvotně uzná v reálné hodnotě. Pokud smlouva o finanční záruce byla poskytnuta nespřízněné straně prostřednictvím samostatné transakce za obvyklých obchodních podmínek, bude se počáteční reálná hodnota pravděpodobně rovnat poskytnuté odměně, neexistuje-li důkaz o opaku. Z toho plyne, že pokud smlouva o finanční záruce byla prvotně zaúčtována v reálné hodnotě do hospodářského výsledku nebo pokud neplatí odstavce 3.2.15–3.2.23 a B3.2.12–B3.2.17 (jestliže převod finančního aktiva nesplňuje podmínky pro vynětí nebo se uplatní metoda přetrvávající angažovanosti), výstavce ji ocení: i) částkou určenou podle oddílu 5.5 nebo ii) částkou prvotně uznanou, sníženou o případnou kumulativní částku příjmů uznaných podle zásad IFRS 15 (viz odst. 4.2.1 písm. c)), je-li vyšší;'),
('3ec40391-e0da-4687-bd26-9ad3a721bff7', 54, 'B2.5', 'b) některé záruky vztahující se k úvěru nevyžadují jako podmínku platby, aby byl držitel vystaven riziku a utrpěl ztrátu v důsledku selhání dlužníka při splacení aktiva, jež je předmětem záruky v době splatnosti. Příkladem takové záruky je smlouva vyžadující úhradu v případě, že úvěrový rating nebo úvěrový index dlužníka poklesne pod určitou hranici. Takové záruky nejsou smlouvami o finanční záruce, jak je definuje tento standard, a nejsou pojistnými smlouvami, jak je definuje IFRS 17. Takové záruky jsou deriváty a výstavce pro ně použije tento standard; c) pokud byla smlouva o finanční záruce vydána v souvislosti s prodejem zboží, výstavce použije při určení okamžiku uznání výnosu ze záruky a z prodeje zboží IFRS 15.'),
('3ec40391-e0da-4687-bd26-9ad3a721bff7', 55, 'UZNÁNÍ A VYNĚTÍ (KAPITOLA 3)', 'Prvotní uznání (oddíl 3.1)'),
('3ec40391-e0da-4687-bd26-9ad3a721bff7', 56, 'B3.1.2', 'a) nepodmíněné pohledávky a závazky se uznají jako aktiva a závazky, pokud se účetní jednotka stala smluvní stranou a pokud v důsledku toho má právní nárok obdržet nebo právní závazek zaplatit hotovost; b) aktiva, která si účetní jednotka pořídí, a závazky, které jí vzniknou jako důsledek závazného příslibu koupit nebo prodat zboží nebo služby, se běžně neuznávají, dokud alespoň jedna ze smluvních stran neposkytla plnění. Například účetní jednotka, která přijala závaznou objednávku, neuznává většinou aktivum (a účetní jednotka, která objednávku zadala, neuznává závazek) v době uzavření smlouvy, ale až v době dodání zboží nebo poskytnutí služeb. Pokud je závazný příslib koupit nebo prodat nefinanční položky v rámci působnosti tohoto standardu podle odstavců 2.4-2.7, jeho čistá reálná hodnota je uznána jako aktivum nebo závazek v den uzavření závazku (viz odstavec B4.1.30 písm. c)). Pokud navíc dříve neuznaný závazný příslib plní funkci zajištěné položky při zajišťování reálné hodnoty, jakákoliv změna v čisté reálné hodnotě, kterou lze přičíst zajišťovanému riziku, je uznána jako aktivum nebo závazek na počátku zajišťovacího vztahu (viz odst. 6.5.8 písm. b) a odstavec 6.5.9));'),
('3ec40391-e0da-4687-bd26-9ad3a721bff7', 57, 'B3.1.2', 'c) forwardová smlouva, která patří do působnosti tohoto standardu (viz odstavec 2.1), je uznána jako aktivum nebo závazek v den uzavření závazku, a nikoli v den vypořádání závazku. Pokud se účetní jednotka stane stranou forwardové smlouvy, reálné hodnoty práv a povinností se často sobě rovnají, takže čistá reálná hodnota forwardu je nulová. Pokud čistá reálná hodnota práv a povinností není nulová, pak je smlouva uznána jako aktivum nebo závazek; d) opční smlouvy, které patří do působnosti tohoto standardu (viz odstavec 2.1), jsou uznány jako aktiva nebo závazky, jakmile se držitel nebo upisovatel stane stranou smlouvy; e) plánované budoucí transakce bez ohledu na míru pravděpodobnosti nejsou aktivy a závazky, protože účetní jednotka se nestala smluvní stranou. Spotový nákup nebo prodej finančních aktiv'),
('3ec40391-e0da-4687-bd26-9ad3a721bff7', 58, 'B3.1.6', 'Vynětí finančních aktiv (oddíl 3.2)'),
('3ec40391-e0da-4687-bd26-9ad3a721bff7', 59, 'B3.2.1', 'Ujednání, na jejichž základě má účetní jednotka smluvní právo získat peněžní toky plynoucí z finančního aktiva, ale také přebírá smluvní závazek zaplatit hotovost jednomu nebo více příjemcům (odst. 3.2.4 písm. b))'),
('3ec40391-e0da-4687-bd26-9ad3a721bff7', 60, 'B3.2.3', 'Posouzení převodu rizik a užitků vyplývajících z vlastnictví(od stavec 3.2.6)'),
('3ec40391-e0da-4687-bd26-9ad3a721bff7', 61, 'B3.2.4', 'a) nepodmíněný prodej finančního aktiva; b) prodej finančního aktiva spolu s opcí na zpětnou koupi finančního aktiva za jeho reálnou hodnotu v době zpětné koupě a c) prodej finančního aktiva spolu s prodejní nebo kupní opcí, která je hluboce „out of money“ (tj. opcí, která je tak daleko „mimo peníze“, že je vysoce nepravděpodobné, že před vypršením přejde do stavu „v penězích“).'),
('3ec40391-e0da-4687-bd26-9ad3a721bff7', 62, 'B3.2.5', 'a) operace prodeje a zpětné koupě, kde cena zpětné koupě je pevná cena nebo prodejní cena plus výnos z investice; b) dohoda o zapůjčení cenných papírů; c) prodej finančního aktiva spolu se swapem celkových výnosů, který přesouvá tržní riziko zpět na účetní jednotku; d) prodej finančního aktiva spolu s prodejní nebo kupní opcí hluboko „in money“ (tj. opcí, která je tak daleko „v penězích“, že je vysoce nepravděpodobné, že před vypršením přejde do stavu „mimo peníze“) a e) prodej krátkodobých pohledávek, kterými účetní jednotka garantuje kompenzovat přejímajícímu úvěrové ztráty, u kterých je pravděpodobné, že nastanou.'),
('3ec40391-e0da-4687-bd26-9ad3a721bff7', 63, 'B3.2.6', 'Posouzení převodu kontroly'),
('3ec40391-e0da-4687-bd26-9ad3a721bff7', 64, 'B3.2.8', 'a) smluvní právo disponovat s převáděným aktivem má malý praktický účinek, pokud pro převáděné aktivum neexistuje trh a b) způsobilost disponovat převáděným aktivem má malý praktický účinek, pokud nemůže být tato způsobilost volně uplatněna. Z toho důvodu: i) způsobilost přejímajícího disponovat převáděným aktivem musí být nezávislá na jednání jiných (tzn. musí to být jednostranná způsobilost) a ii) přejímající musí být způsobilý disponovat převáděným aktivem bez toho, aby bylo potřeba připojit k převodu restriktivní podmínky (např. podmínky o tom, jak má být zacházeno s poskytnutým úvěrem nebo s opcí, která dává přejímajícímu právo zpětné koupě aktiva).'),
('3ec40391-e0da-4687-bd26-9ad3a721bff7', 65, 'B3.2.9', 'Převody, které splňují podmínky pro vynětí'),
('3ec40391-e0da-4687-bd26-9ad3a721bff7', 66, 'B3.2.11', 'Převody, které nesplňují podmínky pro vynětí'),
('3ec40391-e0da-4687-bd26-9ad3a721bff7', 67, 'B3.2.12', 'Přetrvávající angažovanost v převáděných aktivech'),
('3ec40391-e0da-4687-bd26-9ad3a721bff7', 68, 'B3.2.13', 'Všechna aktiva a) Aktiva oceněná naběhlou hodnotou b) Aktiva oceněná reálnou hodnotou c) d) e) Veškeré převody'),
('3ec40391-e0da-4687-bd26-9ad3a721bff7', 69, 'B3.2.15', 'Příklady'),
('3ec40391-e0da-4687-bd26-9ad3a721bff7', 70, 'B3.2.16', 'a) Dohody o zpětném odkupu a půjčky cenných papírů. Pokud je finanční aktivum prodáno na základě dohody o zpětném odkupu za pevnou cenu nebo za prodejní cenu plus výnos z investice, nebo pokud je zapůjčeno na základě dohody o jeho navrácení převádějícímu, pak není vyňato, protože převádějící si ponechal v podstatě všechna rizika a užitky vyplývající z vlastnictví. Pokud přejímající získá právo aktivum prodat nebo zastavit, převádějící musí aktivum ve výkazu o finanční pozici reklasifikovat, například jako půjčené aktivum nebo pohledávku se zpětným odkupem. b) Dohody o zpětném odkupu a půjčky cenných papírů – aktiva, která jsou prakticky stejného charakteru. Pokud je finanční aktivum prodáno na základě dohody o zpětném odkupu stejného nebo prakticky stejného aktiva za pevnou cenu nebo za prodejní cenu plus výnos z investice, nebo pokud je finanční aktivum zapůjčeno na základě dohody o navrácení stejného nebo prakticky stejného aktiva převádějícímu, pak není vyňato, protože převádějící drží v podstatě všechna rizika a užitky vyplývající z vlastnictví.'),
('3ec40391-e0da-4687-bd26-9ad3a721bff7', 71, 'B3.2.16', 'c) Dohody o zpětném odkupu a půjčky cenných papírů – právo substituce. Pokud dohoda o zpětném odkupu za pevnou cenu nebo za cenu rovnající se součtu prodejní ceny a výnosu z investice nebo podobná transakce týkající se půjčky cenných papírů dává přejímajícímu právo nahradit aktiva, která jsou v den zpětné koupě podobná a mají stejnou reálnou hodnotu jako převáděné aktivum, pak prodané nebo zapůjčené aktivum na základě zpětného odkupu nebo půjčky cenných papírů není vyňato, protože převádějící drží v podstatě všechna rizika a užitky vyplývající z vlastnictví. d) Předkupní právo na zpětný odkup aktiva za reálnou hodnotu. Pokud účetní jednotka prodá finanční aktivum a ponechá si pouze předkupní právo na zpětný odkup převáděného aktiva za reálnou hodnotu, v okamžiku, kdy je přejímající prodá, účetní jednotka vyjme aktivum, protože převedla v podstatě všechna rizika a užitky vyplývající z vlastnictví. e) „Wash sale“. Zpětný odkup finančního aktiva krátce po jeho prodeji je někdy nazýván „wash sale“. Takový zpětný odkup nevylučuje vynětí za předpokladu, že původní transakce splnila podmínky pro vynětí. Pokud však dohoda o prodeji finančního aktiva vejde v platnost ve stejnou dobu jako dohoda o zpětném odkupu tohoto aktiva za pevnou cenu nebo prodejní cenu plus výnos z investice, pak se aktivum nevyjme.'),
('3ec40391-e0da-4687-bd26-9ad3a721bff7', 72, 'B3.2.16', 'f) Prodejní opce a kupní opce, které jsou hluboko v penězích. Pokud může být převáděné finanční aktivum koupeno zpět převádějícím uplatněním kupní opce a kupní opce je hluboko v penězích, převod nesplňuje podmínky pro vynětí, protože převádějící drží v podstatě všechna rizika a užitky vyplývající z vlastnictví. Stejně tak pokud může být finanční aktivum zpětně prodáno přejímajícím uplatněním prodejní opce a prodejní opce je hluboko v penězích, převod nesplňuje podmínky pro vynětí, protože převádějící drží v podstatě všechna rizika a užitky vyplývající z vlastnictví. g) Prodejní opce a kupní opce, které jsou hluboko mimo peníze. Finanční aktivum, které je převáděným předmětem jen vzhledem k prodejní opci hluboce mimo peníze držené přijímajícím nebo vzhledem k nákupní opci hluboce mimo peníze držené převádějícím, je vyňato. Dochází k tomu proto, že převádějící převedl v podstatě všechna rizika a odměny plynoucí z vlastnictví. h) Běžně dostupná aktiva podléhající kupní opci, která není ani hluboko v penězích, ani hluboko mimo peníze. Pokud účetní jednotka vlastní opci na nákup aktiva, které je snadno dostupné na trhu, a opce není ani hluboko v penězích, ani hluboko mimo peníze, pak aktivum je vyňato. Dochází k tomu proto, že účetní jednotka i) ani nezadržela, ani nepřevedla v podstatě všechna rizika a užitky vyplývající z vlastnictví a ii) neponechala si kontrolu. Pokud však aktivum není snadno dostupné na trhu, vynětí je vyloučeno do výše hodnoty aktiva podléhajícího kupní opci, protože účetní jednotka si zachovala kontrolu nad aktivem.'),
('3ec40391-e0da-4687-bd26-9ad3a721bff7', 73, 'B3.2.16', 'i) Nesnadno dostupné aktivum podléhající prodejní opci vystavené účetní jednotkou, která není ani hluboko v penězích, ani hluboko mimo peníze. Pokud účetní jednotka převede finanční aktivum, které není snadno dostupné na trhu, a vystaví prodejní opci, která není hluboko mimo peníze, účetní jednotka si neponechá ani nepřevede v podstatě všechna rizika a užitky vyplývající z vlastnictví, a to vzhledem k vystavené prodejní opci. Účetní jednotka si zachová kontrolu nad aktivem, pokud je prodejní opce dostatečně hodnotná, aby zabránila přejímajícímu v prodeji aktiva. V takovém případě se aktivum nepřestává uznávat v rozsahu přetrvávající angažovanosti převádějícího (viz odstavec B3.2.9). Pokud prodejní opce není dostatečně hodnotná, aby zabránila přejímajícímu v prodeji aktiva, účetní jednotka kontrolu nad aktivem převedla. V takovém případě je aktivum vyňato. j) Aktiva s prodejní opcí nebo s kupní opcí nebo s dohodou o budoucím zpětném odkupu. Pokud účetní jednotka převede finanční aktivum s prodejní opcí, s kupní opcí nebo s dohodou o budoucím zpětném odkupu a realizační cena opce, resp. cena zpětného odkupu, se rovná reálné hodnotě finančního aktiva v době zpětného odkupu, bude takové aktivum vyňato, protože došlo k převodu v podstatě všech rizik a užitků vyplývajících z vlastnictví.'),
('3ec40391-e0da-4687-bd26-9ad3a721bff7', 74, 'B3.2.16', 'k) Kupní opce na nákup nebo prodejní opce vypořádaná v hotovosti. Pokud účetní jednotka převádí finanční aktivum s prodejní opcí, kupní opcí nebo s dohodou o budoucím zpětném odkupu, které budou vypořádány čistě v hotovosti, musí posoudit, zda si ponechala, nebo zda převedla v podstatě všechna rizika a užitky vyplývající z vlastnictví. Pokud si účetní jednotka ponechala v podstatě všechna rizika a užitky vyplývající z vlastnictví převáděného aktiva, posoudí, zda si ponechala kontrolu nad převáděným aktivem. To, že je prodejní opce nebo kupní opce, případně dohoda o budoucím zpětném odkupu, vypořádána čistě v hotovosti, automaticky neznamená, že účetní jednotka kontrolu převedla (viz odstavec B3.2.9 a písmena g), h) a i) výše). l) Práva zpětného odkupu („removal of accounts“). Ustanovení „removal of accounts“ je opcí nepodmíněného zpětného odkupu, která dává účetní jednotce právo požadovat navrácení aktiv, jejichž zpětný převod podléhá určitým omezením. Pokud taková opce způsobuje, že si účetní jednotka ani neponechala, ani nepřevedla v podstatě všechna rizika a užitky vyplývající z vlastnictví, pak opce brání vynětí pouze té části aktiva, která podléhá zpětnému odkupu (za předpokladu, že přejímající nemůže aktivum prodat). Pokud například účetní hodnota a výnosy z převodu poskytnutých úvěrů jsou 100 000 MJ, přičemž každý jednotlivý úvěr lze koupit zpět, ale souhrnná hodnota úvěrů koupených zpět nesmí přesáhnout 10 000 MJ, pak podmínky pro vynětí splňují úvěry ve výši 90 000 MJ.'),
('3ec40391-e0da-4687-bd26-9ad3a721bff7', 75, 'B3.2.16', 'm) „Clean-up call“ opce na prodej zbytku. Účetní jednotka, kterou může být i převádějící a jež zajišťuje obsluhu převedených aktiv, může mít „clean-up call“ opci na prodej zbytku. Tato opce jí umožňuje koupit zbývající aktiva v okamžiku, kdy množství nesplacených aktiv klesne pod určitou úroveň, tj. když jsou náklady na obsluhu aktiv vyšší než související přínos. Pokud taková opce způsobuje, že si účetní jednotka ani neponechala, ani nepřevedla v podstatě všechna rizika a užitky vyplývající z vlastnictví, a pokud přejímající nemůže aktivum prodat, opce brání vynětí pouze té části aktiva, která podléhá kupní opci. n) Podřízené podíly a úvěrové záruky. Účetní jednotka může zvýšit kvalitu převedeného úvěrového aktiva tím, že podíl na tomto aktivu, který si ponechala, nebo jeho část podřídí. Dále může kvalitu úvěrového aktiva zvýšit tím, že přejímajícímu poskytne úvěrovou záruku, která může být neomezená nebo omezená určitou částkou. Pokud si účetní jednotka ponechá v podstatě všechna rizika a užitky vyplývající z vlastnictví převáděného aktiva, aktivum se nadále uznává v celém svém rozsahu. Pokud si účetní jednotka ponechá některá, ale ne v podstatě všechna rizika a užitky vyplývající z vlastnictví a ponechá si kontrolu, vyjmout lze pouze tu částku hotovosti nebo jiných aktiv, o jejichž platbu může být účetní jednotka požádána.'),
('3ec40391-e0da-4687-bd26-9ad3a721bff7', 76, 'B3.2.16', 'o) Swap celkových výnosů. Účetní jednotka může prodat finanční aktivum přejímajícímu a vstoupit s ním do swapu celkových výnosů, pomocí něhož budou všechny peněžní toky úrokových plateb z podkladového aktiva postoupeny zpět účetní jednotce směnou za pevnou nebo pohyblivou platbu a všechna zvýšení nebo poklesy reálné hodnoty daného aktiva ponese účetní jednotka. V tomto případě je vynětí celého aktiva zakázáno. p) Úrokové swapy. Účetní jednotka může převést na přejímajícího finanční aktivum s pevnou úrokovou mírou a vstoupit s ním do úrokového swapu za účelem získání pevné úrokové míry a za účelem platby pohyblivé úrokové míry založené na pomyslné hodnotě, která je rovna jistinné hodnotě převáděného finančního aktiva. Úrokový swap nevylučuje vynětí převáděného aktiva za předpokladu, že swapové platby nejsou podmíněny platbami z převáděného aktiva.'),
('3ec40391-e0da-4687-bd26-9ad3a721bff7', 77, 'B3.2.16', 'q) Amortizované úrokové swapy. Účetní jednotka může převést na přejímajícího finanční aktivum s pevnou úrokovou mírou, které se v průběhu času umoří, a vstoupit s ním do amortizovaného úrokového swapu, z jehož pomyslné hodnoty bude přejímající inkasovat částky s pevnou úrokovou mírou a hradit částky s pohyblivou úrokovou mírou. Pokud se pomyslná hodnota swapu odepisuje, takže je rovna jistinné hodnotě převáděného finančního aktiva nesplaceného v každém časovém okamžiku, pak swap obecně způsobí, že si účetní jednotka ponechá podstatné riziko předčasného splacení. V takovém případě účetní jednotka buď pokračuje v uznávání celého převáděného aktiva, nebo v uznávání do výše své přetrvávající angažovanosti. Pokud naopak odpis pomyslné hodnoty swapu není spojen s částkou jistiny, která je nesplacenou částí převáděného aktiva, pak takový swap nezpůsobí, že si účetní jednotka ponechá riziko předčasného splacení aktiva. Proto tato skutečnost nevyloučí vynětí převáděného aktiva za předpokladu, že swapové platby nejsou podmíněny úrokovými platbami z převáděného aktiva a swap nezpůsobí, že si účetní jednotka ponechá jiná podstatná rizika a užitky vyplývající z vlastnictví převáděného aktiva. r) Odpis. Účetní jednotka nemá žádná rozumná očekávání, že smluvní peněžní toky z finančního aktiva jako celku nebo z jeho části získá zpět.'),
('3ec40391-e0da-4687-bd26-9ad3a721bff7', 78, 'B3.2.17', 'Předpokládejme, že účetní jednotka má portfolio úvěrů s možností předčasného splacení, jejichž kupon a efektivní úroková míra je 10 % a jejichž jistinná a naběhlá hodnota je 10,000 MJ. Účetní jednotka uzavře transakci, v níž přejímající na oplátku za platbu ve výši 9,115 MJ získá právo na 9,000 MJ z veškerých inkas jistiny plus úrok sazbou 9,5 %. Účetní jednotka si ponechá právo na 1,000 MJ z veškerých inkas jistiny, na 10 % úrok a dále na zbytkový úrok („excess spread“) ve výši 0,5 % z jistiny ve výši 9,000 MJ. Inkasa z předčasných splátek budou úměrně rozdělena mezi účetní jednotku a přejímajícího v poměru 1:9, ale veškerá selhání dlužníka budou odečtena z podílu účetní jednotky, který činí 1,000 MJ, a to až do jeho vyčerpání. Reálná hodnota úvěrů v den transakce je 10,100 MJ a reálná hodnota zbytkového úroku ve výši 0,5 procenta je 40 MJ. Účetní jednotka určí, že některá podstatná rizika a užitky vyplývající z vlastnictví převedla (například podstatné riziko předčasného splacení), ale také že si některá podstatná rizika a užitky vyplývající z vlastnictví ponechala (vzhledem ke svému podřízenému podílu) a že si ponechala kontrolu. Proto účetní jednotka uplatňuje přístup přetrvávající angažovanosti. Při účtování podle tohoto standardu účetní jednotka transakci analyzuje jako a) zadržení poměrného podílu ve výši 1,000 MJ a jako b) podřízení tohoto podílu s cílem zvýšit kvalitu úvěrového aktiva.'),
('3ec40391-e0da-4687-bd26-9ad3a721bff7', 79, 'B3.2.17', 'Účetní jednotka vypočítá, že hodnota 9,090 MJ (90 % z 10,100 MJ) ze získaného protiplnění ve výši 9,115 MJ představuje protiplnění za poměrný 90% podíl. Zbývající část získaného protiplnění (25 MJ) představuje získané protiplnění za podřízení vlastního podílu s cílem zvýšit kvalitu úvěrového aktiva. Zbytkový úrok ve výši 0,5 % představuje získané protiplnění za zkvalitnění úvěrového aktiva. Takže celkové získané protiplnění za zkvalitnění úvěrového aktiva je 65 MJ (25 MJ + 40 MJ). Účetní jednotka vypočítá zisk nebo ztrátu při prodeji 90 % podílu peněžních toků. Pokud budeme předpokládat, že reálné hodnoty 90 % převedené části a 10 % zadržené části nejsou k datu převodu dostupné, účetní jednotka rozdělí účetní hodnotu aktiva v souladu s odstavcem 3.2.14 IFRS 9 následovně: Reálná hodnota Procentuální podíl Rozdělená účetní hodnota Převedená část 9,090 90  % 9,000 Zadržená část 1,010 10  % 1,000 Celkem 10,100 10,000 Účetní jednotka vypočítá svůj zisk nebo ztrátu při prodeji 90 % podílu peněžních toků odečtením převedené části rozdělené účetní hodnoty od získaného protiplnění, tzn. 90 MJ (9,090 MJ – 9,000 MJ). Účetní hodnota části zadržené účetní jednotkou je 1,000 MJ. Účetní jednotka navíc uzná přetrvávající angažovanost, která vyplývá z podřízení zadrženého podílu. Účetní jednotka tudíž uzná aktivum v hodnotě 1,000 MJ (maximální hodnota peněžních toků, o které může v důsledku podřízení přijít) a příslušný závazek v hodnotě 1,065 MJ (což je maximální hodnota peněžních toků, o které může v důsledku podřízení přijít, tj. 1,000 MJ, plus reálná hodnota podřízení ve výši 65 MJ).')
